                <div key={i} className="flex flex-col group border-l-2 border-stone-100 pl-6 py-2 hover:border-accent-yellow transition-colors bg-stone-50/30">
                  <span className="text-sm md:text-base font-bold text-stone-700 tracking-wider uppercase mb-1">
