import React, { useState, useRef } from 'react';
import { PORTFOLIO_ITEMS } from '../constants';

const PortfolioItemCard: React.FC<{ imageUrl: string; title: string }> = ({ imageUrl, title }) => {
  const [isHovered, setIsHovered] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);
  const lastMousePos = useRef({ x: 0, y: 0 });

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!isHovered) return;
    setIsDragging(true);
    lastMousePos.current = { x: e.clientX, y: e.clientY };
    e.preventDefault();
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !isHovered) return;

    const deltaX = e.clientX - lastMousePos.current.x;
    const deltaY = e.clientY - lastMousePos.current.y;

    setOffset(prev => {
      const newX = prev.x + deltaX;
      const newY = prev.y + deltaY;

      if (containerRef.current) {
        const { width, height } = containerRef.current.getBoundingClientRect();
        const maxOffsetX = (width * 0.6) / 2;
        const maxOffsetY = (height * 0.6) / 2;

        return {
          x: Math.max(-maxOffsetX, Math.min(maxOffsetX, newX)),
          y: Math.max(-maxOffsetY, Math.min(maxOffsetY, newY))
        };
      }
      return { x: newX, y: newY };
    });

    lastMousePos.current = { x: e.clientX, y: e.clientY };
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleMouseLeave = () => {
    setIsHovered(false);
    setIsDragging(false);
    setOffset({ x: 0, y: 0 });
  };

  const handleMouseEnter = () => {
    setIsHovered(true);
  };

  return (
    <div 
      ref={containerRef}
      className="group relative bg-white overflow-hidden aspect-square cursor-grab active:cursor-grabbing border-stone-200 border-[0.5px]"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
    >
      <img 
        src={imageUrl} 
        alt={title} 
        draggable={false}
        className={`w-full h-full object-cover transition-transform duration-500 ease-out select-none pointer-events-none`}
        style={{
          transform: isHovered 
            ? `scale(1.6) translate(${offset.x / 1.6}px, ${offset.y / 1.6}px)` 
            : 'scale(1) translate(0px, 0px)'
        }}
      />
    </div>
  );
};

