const RadarChart: React.FC<{ isVisible: boolean }> = ({ isVisible }) => {
  const size = 600; 
  const center = size / 2;
  const radius = size * 0.3;
  const levels = 5;
  const data = SKILLS;
  const angleStep = (Math.PI * 2) / data.length;

  const gridLevels = Array.from({ length: levels }, (_, i) => (radius / levels) * (i + 1));

  // Points for the animated skill area
  const points = data.map((skill, i) => {
    // When not visible, points collapse toward center for a "bloom" effect
    const factor = isVisible ? (skill.percentage / 100) : 0.1;
    const r = factor * radius;
    const x = center + r * Math.cos(i * angleStep - Math.PI / 2);
    const y = center + r * Math.sin(i * angleStep - Math.PI / 2);
    return `${x},${y}`;
  }).join(' ');

  return (
    <div className={`relative w-full aspect-square max-w-[550px] mx-auto flex items-center justify-center overflow-visible transition-all duration-1000 ease-out ${isVisible ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 translate-y-8'}`}>
      <svg viewBox={`0 0 ${size} ${size}`} className="w-full h-full overflow-visible drop-shadow-sm">
        <defs>
          <linearGradient id="chartBorderGradient" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#fcd34d" /> {/* amber-300 */}
            <stop offset="100%" stopColor="#f59e0b" /> {/* amber-500 */}
          </linearGradient>
        </defs>

        {/* Background Grid Circles */}
        {gridLevels.map((r, i) => (
          <circle
            key={i}
            cx={center}
            cy={center}
            r={r}
            fill="none"
            stroke="#e7e5e4" 
            strokeWidth="0.5" 
            strokeDasharray={i === levels - 1 ? "0" : "4 4"}
          />
        ))}

        {/* Axis Lines */}
        {data.map((_, i) => {
          const x = center + radius * Math.cos(i * angleStep - Math.PI / 2);
          const y = center + radius * Math.sin(i * angleStep - Math.PI / 2);
          return (
            <line
              key={i}
              x1={center}
              y1={center}
              x2={x}
              y2={y}
              stroke="#e7e5e4"
              strokeWidth="0.5"
            />
          );
        })}

        {/* Data Area - Yellow/Orange Fill with Gradient Border */}
