const RadarChart: React.FC<{ isVisible: boolean }> = ({ isVisible }) => {
  const size = 600; 
  const center = size / 2;
  const radius = size * 0.3;
  const levels = 5;
  const data = SKILLS;
  const angleStep = (Math.PI * 2) / data.length;

  const gridLevels = Array.from({ length: levels }, (_, i) => (radius / levels) * (i + 1));

  // Points for the animated skill area
  const points = data.map((skill, i) => {
    // When not visible, points collapse toward center for a "bloom" effect
    const factor = isVisible ? (skill.percentage / 100) : 0.05;
    const r = factor * radius;
    const x = center + r * Math.cos(i * angleStep - Math.PI / 2);
    const y = center + r * Math.sin(i * angleStep - Math.PI / 2);
    return `${x},${y}`;
  }).join(' ');

  return (
    <div className={`relative w-full aspect-square max-w-[550px] flex items-center justify-center overflow-visible transition-all duration-[1200ms] cubic-bezier(0.34, 1.56, 0.64, 1) ${isVisible ? 'opacity-100 scale-100 rotate-0 translate-y-0' : 'opacity-0 scale-75 -rotate-6 translate-y-12'}`}>
      <svg viewBox={`0 0 ${size} ${size}`} className="w-full h-full overflow-visible drop-shadow-[0_10px_30px_rgba(0,0,0,0.05)]">
        <defs>
          <linearGradient id="chartBorderGradient" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#fcd34d" /> {/* amber-300 */}
            <stop offset="100%" stopColor="#f59e0b" /> {/* amber-500 */}
          </linearGradient>
          <filter id="glow">
            <feGaussianBlur stdDeviation="2.5" result="coloredBlur"/>
            <feMerge>
                <feMergeNode in="coloredBlur"/>
                <feMergeNode in="SourceGraphic"/>
            </feMerge>
          </filter>
        </defs>

        {/* Background Grid Circles */}
        {gridLevels.map((r, i) => (
          <circle
            key={i}
            cx={center}
            cy={center}
            r={r}
            fill="none"
            stroke="#e7e5e4" 
            strokeWidth="0.5" 
            strokeDasharray={i === levels - 1 ? "0" : "4 4"}
            className={`transition-opacity duration-1000 delay-${i * 100} ${isVisible ? 'opacity-100' : 'opacity-0'}`}
          />
        ))}

        {/* Axis Lines */}
        {data.map((_, i) => {
          const x = center + radius * Math.cos(i * angleStep - Math.PI / 2);
          const y = center + radius * Math.sin(i * angleStep - Math.PI / 2);
          return (
            <line
              key={i}
              x1={center}
              y1={center}
              x2={x}
              y2={y}
              stroke="#e7e5e4"
              strokeWidth="0.5"
              className={`transition-opacity duration-700 delay-300 ${isVisible ? 'opacity-100' : 'opacity-0'}`}
            />
          );
        })}

        {/* Data Area - Yellow/Orange Fill with Gradient Border */}
        <polygon
          points={points}
          fill="rgba(251, 191, 36, 0.12)"
          stroke="url(#chartBorderGradient)" 
          strokeWidth="3"
          strokeLinejoin="round"
          filter="url(#glow)"
          className="transition-all duration-[1500ms] cubic-bezier(0.34, 1.56, 0.64, 1)"
        />

        {/* Center Point */}
        <circle cx={center} cy={center} r="4" fill="#fbbf24" className={`transition-transform duration-700 ${isVisible ? 'scale-100' : 'scale-0'}`} />

        {/* Labels */}
        {data.map((skill, i) => {
          const labelRadius = radius + 55; 
          const x = center + labelRadius * Math.cos(i * angleStep - Math.PI / 2);
          const y = center + labelRadius * Math.sin(i * angleStep - Math.PI / 2);

          let anchor: "start" | "middle" | "end" = "middle";
          if (x > center + 40) anchor = "start";
          else if (x < center - 40) anchor = "end";

          return (
            <text
              key={i}
              x={x}
              y={y}
              fontSize="11"
              fontWeight="800"
              fill="#57534e"
              textAnchor={anchor}
              style={{ transitionDelay: `${400 + (i * 50)}ms` }}
              className={`tracking-widest uppercase select-none transition-all duration-700 ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}
            >
              <tspan x={x} dy="0.3em">{skill.name}</tspan>
              <tspan x={x} dy="1.4em" fontSize="9" fill="#a8a29e" fontWeight="400">
                {skill.percentage}%
              </tspan>
            </text>
          );
        })}
      </svg>
    </div>
  );
};

